#![doc = include_str!("../README.md")]
//! # postings
//!
//! A small inverted-index core built around postings lists.
//!
//! ## Scope (deliberate)
//!
//! - This crate is **index-only**: it does not store document content.
//! - It supports **candidate generation** with **no false negatives** (a caller may
//!   choose to verify candidates with an exact matcher).
//! - It uses a Lucene-style mental model: immutable "segments" (here: append-only
//!   batches) and logical deletes.
//!
//! ## Optional modules
//!
//! - `postings::codec`: low-level codecs (varint/gap) for postings payloads (in this repo).
//! - `postings::positional` (feature `positional`): positional postings for phrase/proximity evaluation.
//! - `postings::raw` (feature `raw-segment`): byte- and file-backed raw segment reader experiments.
//!
//! ## Non-goals (for now)
//!
//! - Full on-disk compaction
//! - Rich query language beyond candidate generation and sparse top-k scoring

#![forbid(unsafe_code)]
#![warn(missing_docs)]

pub mod codec;

#[cfg(feature = "positional")]
pub mod positional;

#[cfg(feature = "raw-segment")]
pub mod raw;

use std::borrow::Borrow;
use std::collections::{HashMap, HashSet};
use std::hash::Hash;

/// Document identifier.
pub type DocId = u32;

/// Upper bound on dense per-query scratch slots.
///
/// Dense accumulators are faster for small dense indexes, but tying scratch
/// memory only to `max_doc_id` makes large dense corpora allocate tens or
/// hundreds of MiB per query. Above this cap, use sparse accumulation instead.
const MAX_DENSE_SCRATCH_SLOTS: usize = 4_000_000;

#[inline]
fn dense_scratch_limit(live_docs: usize) -> usize {
    live_docs
        .saturating_mul(4)
        .clamp(1024, MAX_DENSE_SCRATCH_SLOTS)
}

/// Trait for term weight types in posting lists.
///
/// `u32` is the default for classical term frequency counts.
/// `f32` enables learned sparse representations (SPLADE, SPLADE++, etc.)
/// where terms carry continuous weights rather than integer frequencies.
pub trait Weight: Copy + Default + std::fmt::Debug + 'static {
    /// Whether every value of this weight type converts to a non-negative `f32`.
    const ALWAYS_NONNEGATIVE: bool = false;

    /// The zero/absent weight.
    fn zero() -> Self;
    /// Accumulate (add) a weight into self.
    fn accumulate(&mut self, other: Self);
    /// Accumulate `other` into self, returning `false` and leaving self
    /// unchanged when the sum does not fit. The default calls
    /// [`accumulate`](Weight::accumulate) and returns `true`.
    fn checked_accumulate(&mut self, other: Self) -> bool {
        self.accumulate(other);
        true
    }
    /// Convert to f32 for scoring.
    fn to_f32(self) -> f32;
    /// Convert to u64 for total doc length accumulation.
    fn to_doc_len(self) -> u64;
}

impl Weight for u32 {
    const ALWAYS_NONNEGATIVE: bool = true;

    #[inline]
    fn zero() -> Self {
        0
    }
    #[inline]
    fn accumulate(&mut self, other: Self) {
        *self += other;
    }
    #[inline]
    fn checked_accumulate(&mut self, other: Self) -> bool {
        match self.checked_add(other) {
            Some(sum) => {
                *self = sum;
                true
            }
            None => false,
        }
    }
    #[inline]
    fn to_f32(self) -> f32 {
        self as f32
    }
    #[inline]
    fn to_doc_len(self) -> u64 {
        self as u64
    }
}

impl Weight for f32 {
    #[inline]
    fn zero() -> Self {
        0.0
    }
    #[inline]
    fn accumulate(&mut self, other: Self) {
        *self += other;
    }
    #[inline]
    fn to_f32(self) -> f32 {
        self
    }
    #[inline]
    fn to_doc_len(self) -> u64 {
        // For float weights, doc length is the count of non-zero terms
        // (not the sum of weights), keeping avg_doc_len meaningful for BM25
        u64::from(self != 0.0)
    }
}

/// Errors returned by `postings`.
#[derive(thiserror::Error, Debug)]
pub enum Error {
    /// The caller attempted to add an already-present document id.
    #[error("document already exists: {0}")]
    DuplicateDocId(DocId),
    /// A term's accumulated weight in one document does not fit the weight
    /// type (`u32` term frequencies summed past `u32::MAX`).
    #[error("term weight overflows in document {doc_id}")]
    WeightOverflow {
        /// The document being added.
        doc_id: DocId,
    },
    /// A document's length does not fit the `u32` stored per document.
    #[error("document {doc_id} is too long: length {len} exceeds u32::MAX")]
    DocumentTooLong {
        /// The document being added.
        doc_id: DocId,
        /// The document's length.
        len: u64,
    },
}

/// Planner output for candidate generation.
///
/// This is the simplest encoding of the key invariant:
/// indexing is allowed to bail out (and fall back to scanning) when a query is too broad.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CandidatePlan {
    /// Use the returned candidates as a search set.
    Candidates(Vec<DocId>),
    /// Bail out: the query is too broad, so the caller should scan all documents.
    ScanAll,
}

/// Configuration for candidate planning / bailout.
#[derive(Debug, Clone, Copy)]
pub struct PlannerConfig {
    /// If an upper bound on candidates exceeds this ratio of the corpus, bail out.
    ///
    /// Note: we estimate using \(\sum_t df(t)\), which is an *upper bound* (can exceed N).
    pub max_candidate_ratio: f32,
    /// If an upper bound on candidates exceeds this absolute count, bail out.
    pub max_candidates: u32,
}

impl Default for PlannerConfig {
    fn default() -> Self {
        Self {
            // Conservative defaults: useful for "index as filter" use-cases.
            max_candidate_ratio: 0.6,
            max_candidates: 200_000,
        }
    }
}

/// Per-document metadata stored inside a segment (delete support only).
///
/// Slimmed down from the original design: `postings` and `doc_len` are now
/// tracked globally on `PostingsIndex`, so a segment only needs the term list
/// for df adjustment on delete.
#[derive(Debug)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(
    feature = "serde",
    serde(bound(
        serialize = "Term: serde::Serialize, W: serde::Serialize",
        deserialize = "Term: serde::Deserialize<'de> + Eq + std::hash::Hash, W: serde::Deserialize<'de>"
    ))
)]
struct Segment<Term, W: Weight = u32> {
    /// doc_id -> unique terms in that doc (for df adjustments on delete).
    doc_terms: HashMap<DocId, Vec<Term>>,
    /// Phantom to keep the W type parameter (serde compat, zero size in practice).
    #[cfg_attr(feature = "serde", serde(skip))]
    _w: std::marker::PhantomData<W>,
}

#[derive(Debug, Clone, Copy)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
struct WeightBounds {
    min: f32,
    max: f32,
    all_finite: bool,
}

impl WeightBounds {
    #[inline]
    fn new(weight: f32) -> Self {
        Self {
            min: weight,
            max: weight,
            all_finite: weight.is_finite(),
        }
    }

    #[inline]
    fn update(&mut self, weight: f32) {
        if weight < self.min {
            self.min = weight;
        }
        if weight > self.max {
            self.max = weight;
        }
        self.all_finite &= weight.is_finite();
    }

    fn from_postings<W: Weight>(postings: &[(DocId, W)]) -> Option<Self> {
        let (_, first_weight) = postings.first()?;
        let mut bounds = Self::new(first_weight.to_f32());
        for &(_, weight) in &postings[1..] {
            bounds.update(weight.to_f32());
        }
        Some(bounds)
    }

    #[inline]
    fn contribution_is_nonnegative(self, query_weight: f32) -> bool {
        self.all_finite
            && query_weight.is_finite()
            && ((query_weight >= 0.0 && self.min >= 0.0)
                || (query_weight <= 0.0 && self.max <= 0.0))
    }
}

impl<Term, W: Weight> Default for Segment<Term, W> {
    fn default() -> Self {
        Self {
            doc_terms: HashMap::new(),
            _w: std::marker::PhantomData,
        }
    }
}

/// A postings-based inverted index with segment-style updates.
///
/// This is an in-memory MVP:
/// - each `add_document` creates a new (small) segment
/// - deletes are logical (we update global stats; segment remains immutable)
#[derive(Debug)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(
    feature = "serde",
    serde(bound(
        serialize = "Term: serde::Serialize, W: serde::Serialize",
        deserialize = "Term: serde::Deserialize<'de> + Eq + std::hash::Hash, W: serde::Deserialize<'de>"
    ))
)]
pub struct PostingsIndex<Term = String, W: Weight = u32> {
    segments: Vec<Segment<Term, W>>,
    /// live doc -> segment index (used by delete to find doc_terms)
    doc_segment: HashMap<DocId, usize>,
    /// live doc -> length
    doc_len: HashMap<DocId, u32>,
    /// term -> df (number of live documents containing term)
    df: HashMap<Term, u32>,
    total_doc_len: u64,
    /// Flat global postings: term -> sorted live (doc_id, weight) list.
    ///
    /// Deletes remove postings eagerly; query hot paths rely on that private
    /// invariant to avoid a per-posting live-doc check.
    global_postings: HashMap<Term, Vec<(DocId, W)>>,
    /// Conservative per-term weight bounds used to select exact scoring fast paths
    /// for weight types whose sign is not statically known.
    ///
    /// Deletes may leave these wider than the live postings list. That is intentional:
    /// stale wider bounds can disable an optimization, but they cannot make the
    /// non-negative-contribution proof unsound.
    #[cfg_attr(feature = "serde", serde(default))]
    term_weight_bounds: HashMap<Term, WeightBounds>,
}

impl<Term, W: Weight> Default for PostingsIndex<Term, W> {
    fn default() -> Self {
        Self {
            segments: Vec::new(),
            doc_segment: HashMap::new(),
            doc_len: HashMap::new(),
            df: HashMap::new(),
            total_doc_len: 0,
            global_postings: HashMap::new(),
            term_weight_bounds: HashMap::new(),
        }
    }
}

impl<Term, W: Weight> PostingsIndex<Term, W>
where
    Term: Clone + Eq + Hash + Ord,
{
    /// Create an empty postings index.
    pub fn new() -> Self {
        Self::default()
    }

    /// Count of live documents currently indexed.
    pub fn num_docs(&self) -> u32 {
        self.doc_len.len() as u32
    }

    /// Average document length (in terms) over live documents.
    pub fn avg_doc_len(&self) -> f32 {
        let n = self.num_docs() as f32;
        if n == 0.0 {
            return 0.0;
        }
        (self.total_doc_len as f32) / n
    }

    /// Iterate live document ids.
    pub fn document_ids(&self) -> impl Iterator<Item = DocId> + '_ {
        self.doc_len.keys().copied()
    }

    /// Document length (in terms). Returns 0 for unknown doc ids.
    pub fn document_len(&self, doc_id: DocId) -> u32 {
        self.doc_len.get(&doc_id).copied().unwrap_or(0)
    }

    /// Document frequency for a term (count of live documents containing term).
    pub fn df<Q>(&self, term: &Q) -> u32
    where
        Term: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.df.get(term).copied().unwrap_or(0)
    }

    /// Iterate all distinct terms present in live documents.
    pub fn terms(&self) -> impl Iterator<Item = &Term> + '_ {
        self.df.keys()
    }

    /// Add a document by doc id and weighted term pairs.
    ///
    /// Each `(term, weight)` pair represents a term and its weight in the document.
    /// For classical indexing, weight is the term frequency (u32).
    /// For learned sparse retrieval (SPLADE), weight is a continuous value (f32).
    ///
    /// Duplicate terms are accumulated (weights summed).
    ///
    /// # Errors
    ///
    /// Returns [`Error::DuplicateDocId`] if `doc_id` already exists; call
    /// `delete_document` first to model updates as delete+add
    /// (segment-style). Returns [`Error::WeightOverflow`] when a term's
    /// summed weight does not fit `W`, and [`Error::DocumentTooLong`] when the
    /// document length does not fit `u32`. The index is unchanged on error.
    pub fn add_weighted_document(
        &mut self,
        doc_id: DocId,
        weighted_terms: &[(Term, W)],
    ) -> Result<(), Error> {
        if self.doc_segment.contains_key(&doc_id) {
            return Err(Error::DuplicateDocId(doc_id));
        }

        let mut term_weights: HashMap<Term, W> = HashMap::new();
        for (t, w) in weighted_terms {
            match term_weights.entry(t.clone()) {
                std::collections::hash_map::Entry::Occupied(mut existing) => {
                    if !existing.get_mut().checked_accumulate(*w) {
                        return Err(Error::WeightOverflow { doc_id });
                    }
                }
                std::collections::hash_map::Entry::Vacant(slot) => {
                    slot.insert(*w);
                }
            }
        }

        // Length is taken over the accumulated per-term weights, so duplicate
        // pairs for one term count once for `f32` and sum for `u32`.
        let doc_length = term_weights
            .values()
            .fold(0u64, |len, w| len.saturating_add(w.to_doc_len()));
        let doc_length = checked_doc_len(doc_id, doc_length)?;
        self.index_document_inner(doc_id, term_weights, doc_length);
        Ok(())
    }

    /// Core indexing logic shared by `add_weighted_document` and `add_document`.
    ///
    /// Caller must check for duplicate doc_id before calling.
    fn index_document_inner(
        &mut self,
        doc_id: DocId,
        term_weights: HashMap<Term, W>,
        doc_length: u32,
    ) {
        let mut doc_terms: Vec<Term> = term_weights.keys().cloned().collect();
        doc_terms.sort_unstable();

        // Keep global postings sorted so lookup and intersection paths can use
        // binary search and galloping search even when callers insert doc ids
        // out of order.
        for (term, w) in &term_weights {
            let postings = self.global_postings.entry(term.clone()).or_default();
            match postings.binary_search_by_key(&doc_id, |(id, _)| *id) {
                Ok(i) => postings[i].1 = *w,
                Err(i) => postings.insert(i, (doc_id, *w)),
            }
            if !W::ALWAYS_NONNEGATIVE {
                let weight = w.to_f32();
                self.term_weight_bounds
                    .entry(term.clone())
                    .and_modify(|bounds| bounds.update(weight))
                    .or_insert_with(|| WeightBounds::new(weight));
            }
        }

        // Update global df before moving doc_terms into the segment.
        for term in &doc_terms {
            *self.df.entry(term.clone()).or_insert(0) += 1;
        }

        // Build a lightweight segment (doc_terms only, for delete support).
        let mut seg = Segment::<Term, W>::default();
        seg.doc_terms.insert(doc_id, doc_terms); // move, not clone

        let seg_idx = self.segments.len();
        self.segments.push(seg);
        self.doc_segment.insert(doc_id, seg_idx);
        self.doc_len.insert(doc_id, doc_length);
        self.total_doc_len += u64::from(doc_length);
    }
}

/// A document length as the `u32` stored per document.
fn checked_doc_len(doc_id: DocId, len: u64) -> Result<u32, Error> {
    u32::try_from(len).map_err(|_| Error::DocumentTooLong { doc_id, len })
}

/// Backward-compatible methods for integer-weighted (classical) postings.
impl<Term> PostingsIndex<Term, u32>
where
    Term: Clone + Eq + Hash + Ord,
{
    /// Add a document by doc id and term stream (classical indexing).
    ///
    /// Terms are counted to produce integer term frequencies.
    /// For weighted terms (SPLADE), use [`add_weighted_document`](PostingsIndex::add_weighted_document).
    ///
    /// # Errors
    ///
    /// Returns [`Error::DuplicateDocId`] if `doc_id` already exists and
    /// [`Error::DocumentTooLong`] when `terms.len()` does not fit `u32`.
    pub fn add_document(&mut self, doc_id: DocId, terms: &[Term]) -> Result<(), Error> {
        if self.doc_segment.contains_key(&doc_id) {
            return Err(Error::DuplicateDocId(doc_id));
        }
        // Checked first, so no term count below can pass u32::MAX.
        let doc_length = checked_doc_len(doc_id, terms.len() as u64)?;
        let mut term_counts: HashMap<Term, u32> = HashMap::new();
        for t in terms {
            *term_counts.entry(t.clone()).or_insert(0) += 1;
        }
        self.index_document_inner(doc_id, term_counts, doc_length);
        Ok(())
    }
}

impl<Term, W: Weight> PostingsIndex<Term, W>
where
    Term: Clone + Eq + Hash + Ord,
{
    /// Logically delete a document (if present).
    ///
    /// Returns true if the doc existed.
    pub fn delete_document(&mut self, doc_id: DocId) -> bool {
        let seg_idx = match self.doc_segment.remove(&doc_id) {
            Some(i) => i,
            None => return false,
        };
        let doc_len = self.doc_len.remove(&doc_id).unwrap_or(0);
        self.total_doc_len = self.total_doc_len.saturating_sub(doc_len as u64);

        let seg = &self.segments[seg_idx];
        if let Some(terms) = seg.doc_terms.get(&doc_id) {
            for term in terms {
                if let Some(df) = self.df.get_mut(term) {
                    *df = df.saturating_sub(1);
                    if *df == 0 {
                        self.df.remove(term);
                    }
                }
                if let Some(postings) = self.global_postings.get_mut(term) {
                    let removed_weight =
                        if let Ok(i) = postings.binary_search_by_key(&doc_id, |(id, _)| *id) {
                            let removed_weight = postings[i].1.to_f32();
                            postings.remove(i);
                            Some(removed_weight)
                        } else {
                            None
                        };
                    if postings.is_empty() {
                        self.global_postings.remove(term);
                        self.term_weight_bounds.remove(term);
                    } else if !W::ALWAYS_NONNEGATIVE {
                        if let Some(removed_weight) = removed_weight {
                            let recompute_bounds = match self.term_weight_bounds.get(term).copied()
                            {
                                Some(bounds) => {
                                    !removed_weight.is_finite()
                                        || removed_weight <= bounds.min
                                        || removed_weight >= bounds.max
                                }
                                None => true,
                            };
                            if recompute_bounds {
                                if let Some(bounds) = WeightBounds::from_postings(postings) {
                                    self.term_weight_bounds.insert(term.clone(), bounds);
                                }
                            }
                        }
                    }
                }
            }
        }
        true
    }

    /// Term weight (frequency) of `term` in `doc_id`.
    ///
    /// Returns `W::zero()` if the term is not present or the doc is unknown.
    /// For classical indexes (`W = u32`), this is the term frequency count.
    /// For learned sparse indexes (`W = f32`), this is the SPLADE weight.
    pub fn term_frequency<Q>(&self, doc_id: DocId, term: &Q) -> W
    where
        Term: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        // Doc must be live.
        if !self.doc_segment.contains_key(&doc_id) {
            return W::zero();
        }
        let postings = match self.global_postings.get(term) {
            Some(p) => p,
            None => return W::zero(),
        };
        match postings.binary_search_by_key(&doc_id, |(id, _)| *id) {
            Ok(i) => postings[i].1,
            Err(_) => W::zero(),
        }
    }

    /// Candidate documents that contain at least one query term.
    pub fn candidates<Q>(&self, query_terms: &[Q]) -> Vec<DocId>
    where
        Term: Borrow<Q>,
        Q: Hash + Eq,
    {
        if query_terms.is_empty() {
            return Vec::new();
        }
        let mut lists: Vec<&[(DocId, W)]> = Vec::new();
        if query_terms.len() <= 32 {
            let mut seen_terms: Vec<&Q> = Vec::with_capacity(query_terms.len());
            'term: for term in query_terms {
                for seen in &seen_terms {
                    if *seen == term {
                        continue 'term;
                    }
                }
                seen_terms.push(term);
                if let Some(postings) = self.global_postings.get(term) {
                    if !postings.is_empty() {
                        lists.push(postings);
                    }
                }
            }
        } else {
            let mut seen_terms: HashSet<&Q> = HashSet::new();
            for term in query_terms {
                if !seen_terms.insert(term) {
                    continue;
                }
                if let Some(postings) = self.global_postings.get(term) {
                    if !postings.is_empty() {
                        lists.push(postings);
                    }
                }
            }
        }
        if lists.is_empty() {
            return Vec::new();
        }
        if lists.len() == 1 {
            return lists[0].iter().map(|(id, _)| *id).collect();
        }

        // For dense doc-id lists, one mark pass avoids repeated
        // pairwise union allocation. Sparse doc-id spaces keep the sorted merge path.
        if lists.len() >= 2 {
            let dense_slots = lists
                .iter()
                .filter_map(|postings| {
                    let (last_doc_id, _) = postings.last()?;
                    usize::try_from(*last_doc_id).ok()?.checked_add(1)
                })
                .max()
                .unwrap_or(0);
            let dense_limit = dense_scratch_limit(self.doc_len.len());
            if dense_slots <= dense_limit {
                let mut seen = vec![false; dense_slots];
                for postings in lists {
                    for &(doc_id, _) in postings {
                        seen[doc_id as usize] = true;
                    }
                }
                return seen
                    .into_iter()
                    .enumerate()
                    .filter_map(|(doc_id, hit)| hit.then_some(doc_id as DocId))
                    .collect();
            }
        }

        lists.sort_by_key(|postings| postings.len());
        let mut lists = lists.into_iter();
        let mut out: Vec<DocId> = lists
            .next()
            .map(|postings| postings.iter().map(|(id, _)| *id).collect())
            .unwrap_or_default();
        for docs in lists {
            out = union_sorted_postings(&out, docs);
        }
        out
    }

    /// Candidate documents that contain **all** query terms (conjunctive / AND).
    ///
    /// This is a common first step before:
    /// - exact phrase/proximity verification (positional index), or
    /// - scoring (BM25/TF-IDF) in a higher layer.
    ///
    /// Notes:
    /// - Duplicate terms in `query_terms` are treated as a single requirement.
    /// - Results are returned in sorted order.
    pub fn candidates_all_terms<Q>(&self, query_terms: &[Q]) -> Vec<DocId>
    where
        Term: Borrow<Q>,
        Q: Hash + Eq,
    {
        if query_terms.is_empty() {
            return Vec::new();
        }

        let mut lists: Vec<&[(DocId, W)]> = Vec::new();
        if query_terms.len() <= 32 {
            let mut uniq: Vec<&Q> = Vec::new();
            'term: for term in query_terms {
                for seen in &uniq {
                    if *seen == term {
                        continue 'term;
                    }
                }
                uniq.push(term);
                let Some(postings) = self.global_postings.get(term) else {
                    return Vec::new();
                };
                if postings.is_empty() {
                    return Vec::new();
                }
                lists.push(postings);
            }
        } else {
            let mut seen: HashSet<&Q> = HashSet::new();
            for t in query_terms {
                if seen.insert(t) {
                    let Some(postings) = self.global_postings.get(t) else {
                        return Vec::new();
                    };
                    if postings.is_empty() {
                        return Vec::new();
                    }
                    lists.push(postings);
                }
            }
        }
        if lists.is_empty() {
            return Vec::new();
        }

        // DAAT-style intersection over sorted doc-id lists.
        // Anchor on the rarest term to minimize intermediate sets.
        lists.sort_by_key(|postings| postings.len());

        // Collect doc ids for the rarest term; global postings are sorted and
        // delete removes stale entries eagerly.
        let mut acc: Vec<DocId> = lists[0].iter().map(|(id, _)| *id).collect();

        for list in lists.into_iter().skip(1) {
            acc = intersect_sorted_postings(&acc, list);
            if acc.is_empty() {
                break;
            }
        }
        acc
    }

    /// Plan candidate generation, with a bailout option for broad queries.
    ///
    /// Returns:
    /// - `CandidatePlan::Candidates` when the query is selective enough.
    /// - `CandidatePlan::ScanAll` when the query is too broad (caller should scan all docs).
    pub fn plan_candidates<Q>(&self, query_terms: &[Q], cfg: PlannerConfig) -> CandidatePlan
    where
        Term: Borrow<Q>,
        Q: Hash + Eq,
    {
        if query_terms.is_empty() {
            return CandidatePlan::Candidates(Vec::new());
        }

        let n = self.num_docs();
        if n == 0 {
            return CandidatePlan::Candidates(Vec::new());
        }

        // Upper bound on candidate count: sum df(t) over unique terms.
        let mut df_sum: u64 = 0;
        if query_terms.len() <= 32 {
            let mut seen_terms: Vec<&Q> = Vec::with_capacity(query_terms.len());
            'term: for term in query_terms {
                for seen in &seen_terms {
                    if *seen == term {
                        continue 'term;
                    }
                }
                seen_terms.push(term);
                df_sum = df_sum.saturating_add(self.df(term) as u64);
                if df_sum > cfg.max_candidates as u64 {
                    return CandidatePlan::ScanAll;
                }
            }
        } else {
            let mut seen_terms: HashSet<&Q> = HashSet::new();
            for t in query_terms {
                if !seen_terms.insert(t) {
                    continue;
                }
                df_sum = df_sum.saturating_add(self.df(t) as u64);
                if df_sum > cfg.max_candidates as u64 {
                    return CandidatePlan::ScanAll;
                }
            }
        }

        let ratio = (df_sum as f32) / (n as f32);
        if ratio > cfg.max_candidate_ratio {
            return CandidatePlan::ScanAll;
        }

        CandidatePlan::Candidates(self.candidates(query_terms))
    }

    /// Iterate postings for a term across all segments (live docs only).
    ///
    /// Reads from the global flat postings map in O(1) and filters out
    /// logically-deleted documents.
    pub fn postings_iter<'a, Q>(&'a self, term: &'a Q) -> impl Iterator<Item = (DocId, W)> + 'a
    where
        Term: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.global_postings
            .get(term)
            .into_iter()
            .flat_map(|v| v.iter().copied())
            .filter(|(doc_id, _)| self.doc_segment.contains_key(doc_id))
    }

    fn weight_bounds<Q>(&self, term: &Q, postings: &[(DocId, W)]) -> Option<WeightBounds>
    where
        Term: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.term_weight_bounds
            .get(term)
            .copied()
            .or_else(|| WeightBounds::from_postings(postings))
    }

    fn contributions_are_nonnegative<Q>(
        &self,
        term: &Q,
        postings: &[(DocId, W)],
        query_weight: f32,
    ) -> bool
    where
        Term: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if !query_weight.is_finite() {
            return false;
        }
        if W::ALWAYS_NONNEGATIVE {
            return query_weight >= 0.0;
        }
        self.weight_bounds(term, postings)
            .is_some_and(|bounds| bounds.contribution_is_nonnegative(query_weight))
    }

    /// Return the top `k` documents by sparse inner product.
    ///
    /// Query terms are borrowed so a `PostingsIndex<String, f32>` can be queried
    /// with `&str` terms without allocating. Duplicate query terms are
    /// accumulated before scoring. Ties are broken by ascending doc id.
    pub fn top_k_weighted<Q>(&self, query_terms: &[(&Q, f32)], k: usize) -> Vec<(DocId, f32)>
    where
        Term: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if k == 0 || query_terms.is_empty() {
            return Vec::new();
        }
        if query_terms.len() == 1 {
            let (term, query_weight) = query_terms[0];
            if query_weight == 0.0 {
                return Vec::new();
            }
            let Some(postings) = self.global_postings.get(term) else {
                return Vec::new();
            };
            return top_k_single_postings(postings, query_weight, k);
        }

        let mut lists = Vec::with_capacity(query_terms.len());
        let mut total_postings = 0usize;
        // Short learned-sparse query expansions are cheaper to dedupe linearly
        // than through a hash table; longer queries keep the bounded hash path.
        if query_terms.len() <= 32 {
            let mut query_weights: Vec<(&Q, f32)> = Vec::with_capacity(query_terms.len());
            'term: for &(term, weight) in query_terms {
                if weight == 0.0 {
                    continue;
                }
                for (existing_term, existing_weight) in &mut query_weights {
                    if *existing_term == term {
                        *existing_weight += weight;
                        continue 'term;
                    }
                }
                query_weights.push((term, weight));
            }
            if query_weights.is_empty() {
                return Vec::new();
            }
            for (term, query_weight) in query_weights {
                if query_weight == 0.0 {
                    continue;
                }
                let Some(postings) = self.global_postings.get(term) else {
                    continue;
                };
                if postings.is_empty() {
                    continue;
                }
                total_postings = total_postings.saturating_add(postings.len());
                lists.push((term, postings.as_slice(), query_weight));
            }
        } else {
            let mut query_weights: HashMap<&Q, f32> = HashMap::new();
            for &(term, weight) in query_terms {
                if weight == 0.0 {
                    continue;
                }
                *query_weights.entry(term).or_insert(0.0) += weight;
            }
            if query_weights.is_empty() {
                return Vec::new();
            }
            for (term, query_weight) in query_weights {
                if query_weight == 0.0 {
                    continue;
                }
                let Some(postings) = self.global_postings.get(term) else {
                    continue;
                };
                if postings.is_empty() {
                    continue;
                }
                total_postings = total_postings.saturating_add(postings.len());
                lists.push((term, postings.as_slice(), query_weight));
            }
        }
        if lists.is_empty() {
            return Vec::new();
        }

        if lists.len() == 1 {
            let (_, postings, query_weight) = lists[0];
            return top_k_single_postings(postings, query_weight, k);
        }

        let dense_slots = lists
            .iter()
            .filter_map(|(_, postings, _)| {
                let (last_doc_id, _) = postings.last()?;
                usize::try_from(*last_doc_id).ok()?.checked_add(1)
            })
            .max()
            .unwrap_or(0);
        let dense_limit = dense_scratch_limit(self.doc_len.len());
        if dense_slots <= dense_limit {
            let mut scores = vec![0.0; dense_slots];
            let mut touched = Vec::with_capacity(total_postings.min(self.doc_len.len()));

            let contributions_are_nonnegative =
                lists.iter().all(|(term, postings, query_weight)| {
                    self.contributions_are_nonnegative(*term, postings, *query_weight)
                });

            if contributions_are_nonnegative {
                for (_, postings, query_weight) in lists {
                    for &(doc_id, doc_weight) in postings {
                        let contribution = query_weight * doc_weight.to_f32();
                        if contribution == 0.0 {
                            continue;
                        }
                        let slot = doc_id as usize;
                        if scores[slot] == 0.0 {
                            touched.push(doc_id);
                        }
                        scores[slot] += contribution;
                    }
                }
            } else {
                let mut seen = vec![false; dense_slots];
                for (_, postings, query_weight) in lists {
                    for &(doc_id, doc_weight) in postings {
                        let contribution = query_weight * doc_weight.to_f32();
                        if contribution == 0.0 {
                            continue;
                        }
                        let slot = doc_id as usize;
                        if !seen[slot] {
                            seen[slot] = true;
                            touched.push(doc_id);
                        }
                        scores[slot] += contribution;
                    }
                }
            }

            return top_k_scored_docs(
                touched
                    .into_iter()
                    .map(|doc_id| (doc_id, scores[doc_id as usize])),
                k,
            );
        }

        let mut scores: HashMap<DocId, f32> =
            HashMap::with_capacity(total_postings.min(self.doc_len.len()));
        for (_, postings, query_weight) in lists {
            for &(doc_id, doc_weight) in postings {
                let contribution = query_weight * doc_weight.to_f32();
                if contribution != 0.0 {
                    *scores.entry(doc_id).or_insert(0.0) += contribution;
                }
            }
        }

        top_k_scored_docs(scores, k)
    }

    /// Save the index to a directory using `durability`.
    ///
    /// The file is a versioned envelope: an 8-byte magic, a format version,
    /// the payload length and its CRC-32, then the postcard-encoded index.
    ///
    /// **Format note**: the on-disk layout changed in 0.2.0 when the internal
    /// `global_postings` field was added for query performance.  Data written
    /// by 0.1.x cannot be read by 0.2.0+ and vice-versa. 0.7.0 added the
    /// envelope; [`load`](Self::load) still reads unframed 0.2.0+ files.
    #[cfg(feature = "persistence")]
    pub fn save<D: durability::Directory + ?Sized>(
        &self,
        dir: &D,
        path: &str,
    ) -> Result<(), Box<dyn std::error::Error>>
    where
        Term: serde::Serialize,
        W: serde::Serialize,
    {
        let bytes = frame_saved_index(&postcard::to_allocvec(self)?);
        dir.atomic_write(path, &bytes)?;
        Ok(())
    }

    /// Save the index with stable-storage durability barriers.
    ///
    /// This is strictly stronger than `save()` on filesystem-backed directories:
    /// it fsyncs the temp file and syncs the parent directory after the atomic rename.
    ///
    /// For non-filesystem backends (e.g. `MemoryDirectory`) this returns `NotSupported`.
    #[cfg(feature = "persistence")]
    pub fn save_durable<D: durability::Directory + ?Sized>(
        &self,
        dir: &D,
        path: &str,
    ) -> Result<(), Box<dyn std::error::Error>>
    where
        Term: serde::Serialize,
        W: serde::Serialize,
    {
        let bytes = frame_saved_index(&postcard::to_allocvec(self)?);
        dir.atomic_write_durable(path, &bytes)?;
        Ok(())
    }

    /// Load the index from a directory using `durability`.
    ///
    /// A file written by [`save`](Self::save) must carry a supported format
    /// version and a matching length and CRC-32. An unframed file from an
    /// earlier release is read as a bare postcard payload. Either way the
    /// decoded index must satisfy the in-memory invariants queries rely on
    /// (sorted live postings, consistent document frequencies, lengths and
    /// per-document terms); otherwise this returns an
    /// [`std::io::ErrorKind::InvalidData`] error.
    #[cfg(feature = "persistence")]
    pub fn load<D: durability::Directory + ?Sized>(
        dir: &D,
        path: &str,
    ) -> Result<Self, Box<dyn std::error::Error>>
    where
        for<'de> Term: serde::Deserialize<'de>,
        for<'de> W: serde::Deserialize<'de>,
    {
        use std::io::Read;

        let mut f = dir.open_file(path)?;
        let mut bytes = Vec::new();
        f.read_to_end(&mut bytes)?;
        let idx: Self = postcard::from_bytes(unframe_saved_index(&bytes)?)?;
        idx.check_invariants()
            .map_err(|reason| std::io::Error::new(std::io::ErrorKind::InvalidData, reason))?;
        Ok(idx)
    }

    /// Checks the private invariants that query paths rely on, for an index
    /// decoded from untrusted bytes.
    #[cfg(feature = "persistence")]
    fn check_invariants(&self) -> Result<(), &'static str> {
        if self.doc_segment.len() != self.doc_len.len() {
            return Err("saved index live-document maps disagree");
        }
        let mut total_doc_len = 0u64;
        let mut doc_term_count = 0usize;
        for (doc_id, len) in &self.doc_len {
            total_doc_len += u64::from(*len);
            let terms = self
                .doc_segment
                .get(doc_id)
                .and_then(|segment| self.segments.get(*segment))
                .and_then(|segment| segment.doc_terms.get(doc_id))
                .ok_or("saved index live document has no segment terms")?;
            if !terms.windows(2).all(|pair| pair[0] < pair[1]) {
                return Err("saved index document terms are not sorted and unique");
            }
            for term in terms {
                let has_posting = self.global_postings.get(term).is_some_and(|postings| {
                    postings.binary_search_by_key(doc_id, |(id, _)| *id).is_ok()
                });
                if !has_posting {
                    return Err("saved index document term has no posting");
                }
            }
            doc_term_count += terms.len();
        }
        if total_doc_len != self.total_doc_len {
            return Err("saved index total document length disagrees");
        }
        if self.df.len() != self.global_postings.len() {
            return Err("saved index document frequencies disagree with postings");
        }
        let mut posting_count = 0usize;
        for (term, postings) in &self.global_postings {
            if postings.is_empty()
                || u32::try_from(postings.len()).ok() != self.df.get(term).copied()
            {
                return Err("saved index document frequencies disagree with postings");
            }
            if !postings.windows(2).all(|pair| pair[0].0 < pair[1].0) {
                return Err("saved index postings are not strictly sorted");
            }
            if postings
                .iter()
                .any(|(doc_id, _)| !self.doc_len.contains_key(doc_id))
            {
                return Err("saved index posting names a document that is not live");
            }
            if let Some(bounds) = self.term_weight_bounds.get(term) {
                let covered = postings.iter().all(|(_, weight)| {
                    let weight = weight.to_f32();
                    if weight.is_finite() {
                        bounds.min <= weight && weight <= bounds.max
                    } else {
                        !bounds.all_finite
                    }
                });
                if !covered {
                    return Err("saved index term weight bounds do not cover postings");
                }
            }
            posting_count += postings.len();
        }
        if posting_count != doc_term_count {
            return Err("saved index postings disagree with document terms");
        }
        Ok(())
    }
}

/// Leading bytes of an index written by [`PostingsIndex::save`].
#[cfg(feature = "persistence")]
const SAVED_INDEX_MAGIC: &[u8; 8] = b"POSTIDX\0";
/// Envelope format version written after [`SAVED_INDEX_MAGIC`].
#[cfg(feature = "persistence")]
const SAVED_INDEX_VERSION: u32 = 1;
/// Magic, version (u32), payload length (u64) and payload CRC-32 (u32).
#[cfg(feature = "persistence")]
const SAVED_INDEX_HEADER_LEN: usize = 8 + 4 + 8 + 4;

/// Wraps a postcard payload in the versioned, checksummed envelope.
#[cfg(feature = "persistence")]
fn frame_saved_index(payload: &[u8]) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(SAVED_INDEX_HEADER_LEN + payload.len());
    bytes.extend_from_slice(SAVED_INDEX_MAGIC);
    bytes.extend_from_slice(&SAVED_INDEX_VERSION.to_le_bytes());
    bytes.extend_from_slice(&(payload.len() as u64).to_le_bytes());
    bytes.extend_from_slice(&crc32fast::hash(payload).to_le_bytes());
    bytes.extend_from_slice(payload);
    bytes
}

/// The postcard payload of a saved index: the checked body of an envelope,
/// or the whole file for an unframed index written before 0.7.0.
#[cfg(feature = "persistence")]
fn unframe_saved_index(bytes: &[u8]) -> Result<&[u8], std::io::Error> {
    let invalid = |reason| std::io::Error::new(std::io::ErrorKind::InvalidData, reason);
    let Some(rest) = bytes.strip_prefix(SAVED_INDEX_MAGIC.as_slice()) else {
        return Ok(bytes);
    };
    if bytes.len() < SAVED_INDEX_HEADER_LEN {
        return Err(invalid("saved index header is truncated"));
    }
    let (version, rest) = rest.split_at(4);
    let (len, rest) = rest.split_at(8);
    let (crc, payload) = rest.split_at(4);
    let version = u32::from_le_bytes(version.try_into().expect("4-byte field"));
    if version != SAVED_INDEX_VERSION {
        return Err(invalid("saved index format version is not supported"));
    }
    let len = u64::from_le_bytes(len.try_into().expect("8-byte field"));
    if u64::try_from(payload.len()).ok() != Some(len) {
        return Err(invalid(
            "saved index payload length disagrees with its header",
        ));
    }
    if crc32fast::hash(payload) != u32::from_le_bytes(crc.try_into().expect("4-byte field")) {
        return Err(invalid("saved index checksum mismatch"));
    }
    Ok(payload)
}

fn union_sorted_postings<W>(a: &[DocId], b: &[(DocId, W)]) -> Vec<DocId> {
    let mut out = Vec::with_capacity(a.len().saturating_add(b.len()));
    let mut i = 0usize;
    let mut j = 0usize;

    while i < a.len() && j < b.len() {
        match a[i].cmp(&b[j].0) {
            std::cmp::Ordering::Equal => {
                push_unique(&mut out, a[i]);
                i += 1;
                j += 1;
            }
            std::cmp::Ordering::Less => {
                push_unique(&mut out, a[i]);
                i += 1;
            }
            std::cmp::Ordering::Greater => {
                push_unique(&mut out, b[j].0);
                j += 1;
            }
        }
    }
    while i < a.len() {
        push_unique(&mut out, a[i]);
        i += 1;
    }
    while j < b.len() {
        push_unique(&mut out, b[j].0);
        j += 1;
    }
    out
}

#[inline]
fn push_unique(out: &mut Vec<DocId>, doc_id: DocId) {
    if out.last().copied() != Some(doc_id) {
        out.push(doc_id);
    }
}

fn intersect_sorted_postings<W>(a: &[DocId], b: &[(DocId, W)]) -> Vec<DocId> {
    let mut out = Vec::with_capacity(a.len().min(b.len()));
    if a.is_empty() || b.is_empty() {
        return out;
    }
    let min_len = a.len().min(b.len());
    let max_len = a.len().max(b.len());
    if max_len <= min_len.saturating_mul(8) {
        let mut i = 0usize;
        let mut j = 0usize;
        while i < a.len() && j < b.len() {
            match a[i].cmp(&b[j].0) {
                std::cmp::Ordering::Equal => {
                    out.push(a[i]);
                    i += 1;
                    j += 1;
                }
                std::cmp::Ordering::Less => i += 1,
                std::cmp::Ordering::Greater => j += 1,
            }
        }
        return out;
    }

    // Galloping (exponential search) intersection.
    // Invariant: when a[i] != b[j], advance the cursor of the *smaller*
    // value by gallopping it forward to the *larger* value.  Both cursors
    // always make progress (gallop_forward returns strictly > start when
    // the target is not at start), so the loop terminates.
    let mut i = 0usize;
    let mut j = 0usize;

    while i < a.len() && j < b.len() {
        match a[i].cmp(&b[j].0) {
            std::cmp::Ordering::Equal => {
                out.push(a[i]);
                i += 1;
                j += 1;
            }
            std::cmp::Ordering::Less => {
                // a[i] < b[j]: gallop a forward to reach b[j].
                i = gallop_forward(a, i, b[j].0);
            }
            std::cmp::Ordering::Greater => {
                // b[j] < a[i]: gallop b forward to reach a[i].
                j = gallop_forward_postings(b, j, a[i]);
            }
        }
    }
    out
}

/// Returns the first index `>= start` in `list` such that `list[idx] >= target`,
/// or `list.len()` if no such index exists.  Uses exponential probing + binary
/// search so cost is O(log(gap)) rather than O(gap).
#[inline]
fn gallop_forward(list: &[DocId], start: usize, target: DocId) -> usize {
    if start >= list.len() || list[start] >= target {
        return start;
    }
    let mut step = 1usize;
    // Exponential probe to find an upper bound.
    while start + step < list.len() && list[start + step] < target {
        step <<= 1;
    }
    // Binary search in [start + step/2, start + step).
    let lo = start + (step >> 1);
    let hi = (start + step).min(list.len());
    match list[lo..hi].binary_search(&target) {
        Ok(k) => lo + k,
        Err(k) => lo + k,
    }
}

/// Postings-list equivalent of `gallop_forward`.
#[inline]
fn gallop_forward_postings<W>(list: &[(DocId, W)], start: usize, target: DocId) -> usize {
    if start >= list.len() || list[start].0 >= target {
        return start;
    }
    let mut step = 1usize;
    while start + step < list.len() && list[start + step].0 < target {
        step <<= 1;
    }
    let lo = start + (step >> 1);
    let hi = (start + step).min(list.len());
    match list[lo..hi].binary_search_by_key(&target, |(id, _)| *id) {
        Ok(k) => lo + k,
        Err(k) => lo + k,
    }
}

#[inline]
fn cmp_doc_scores(a: &(DocId, f32), b: &(DocId, f32)) -> std::cmp::Ordering {
    b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0))
}

#[inline]
fn keep_top_k(ranked: &mut Vec<(DocId, f32)>, k: usize) {
    if ranked.len() > k {
        ranked.select_nth_unstable_by(k, cmp_doc_scores);
        ranked.truncate(k);
    }
    ranked.sort_by(cmp_doc_scores);
}

fn top_k_scored_docs<I>(docs: I, k: usize) -> Vec<(DocId, f32)>
where
    I: IntoIterator<Item = (DocId, f32)>,
{
    if k == 0 {
        return Vec::new();
    }

    let mut ranked: Vec<(DocId, f32)> = Vec::with_capacity(k);
    let mut sorted = false;
    for doc in docs {
        if doc.1 == 0.0 {
            continue;
        }
        if ranked.len() < k {
            ranked.push(doc);
            continue;
        }
        if !sorted {
            ranked.sort_by(cmp_doc_scores);
            sorted = true;
        }
        if cmp_doc_scores(&doc, ranked.last().expect("top-k buffer is full")).is_lt() {
            let last = ranked.len() - 1;
            ranked[last] = doc;
            let mut i = last;
            while i > 0 && cmp_doc_scores(&ranked[i], &ranked[i - 1]).is_lt() {
                ranked.swap(i, i - 1);
                i -= 1;
            }
        }
    }
    if !sorted {
        ranked.sort_by(cmp_doc_scores);
    }
    ranked
}

fn top_k_single_postings<W: Weight>(
    postings: &[(DocId, W)],
    query_weight: f32,
    k: usize,
) -> Vec<(DocId, f32)> {
    if k == 0 {
        return Vec::new();
    }
    if postings.len() > k {
        let mut ranked: Vec<(DocId, f32)> = Vec::with_capacity(k);
        let mut sorted = false;
        for &(doc_id, doc_weight) in postings {
            let score = query_weight * doc_weight.to_f32();
            if score == 0.0 {
                continue;
            }
            if ranked.len() < k {
                ranked.push((doc_id, score));
                continue;
            }
            if !sorted {
                ranked.sort_by(cmp_doc_scores);
                sorted = true;
            }
            let candidate = (doc_id, score);
            if cmp_doc_scores(&candidate, ranked.last().expect("top-k buffer is full")).is_lt() {
                let last = ranked.len() - 1;
                ranked[last] = candidate;
                let mut i = last;
                while i > 0 && cmp_doc_scores(&ranked[i], &ranked[i - 1]).is_lt() {
                    ranked.swap(i, i - 1);
                    i -= 1;
                }
            }
        }
        if !sorted {
            ranked.sort_by(cmp_doc_scores);
        }
        return ranked;
    }

    let mut ranked = Vec::with_capacity(postings.len());
    for &(doc_id, doc_weight) in postings {
        let score = query_weight * doc_weight.to_f32();
        if score != 0.0 {
            ranked.push((doc_id, score));
        }
    }
    keep_top_k(&mut ranked, k);
    ranked
}

