        idx.add_document(1, &[String::from("a")]).unwrap();

        assert_eq!(idx.candidates(&[String::from("a")]), vec![1, 2]);
        assert_eq!(idx.term_frequency(1, "a"), 1);
        assert_eq!(idx.term_frequency(2, "a"), 1);
    }

