        assert_eq!(idx.candidates(&[String::from("a")]), vec![1, 7]);
        assert_eq!(idx.term_frequency(1, "a"), 1);
        assert_eq!(idx.term_frequency(4, "a"), 0);
        assert_eq!(idx.term_frequency(7, "a"), 1);
    }

