    fn exact_sparse_top_k(
        docs: &[(DocId, std::collections::HashMap<u8, f32>)],
        query_terms: &[(u8, f32)],
        k: usize,
    ) -> Vec<(DocId, f32)> {
        if k == 0 || query_terms.is_empty() {
            return Vec::new();
        }

        let mut query_weights: std::collections::HashMap<u8, f32> =
            std::collections::HashMap::new();
        for &(term, weight) in query_terms {
            if weight != 0.0 {
                *query_weights.entry(term).or_insert(0.0) += weight;
            }
        }

        let mut scored = Vec::new();
        for &(doc_id, ref doc_weights) in docs {
            let mut score = 0.0;
            for (&term, &query_weight) in &query_weights {
                if let Some(&doc_weight) = doc_weights.get(&term) {
                    let contribution = query_weight * doc_weight;
                    if contribution != 0.0 {
                        score += contribution;
                    }
                }
            }
            if score != 0.0 {
                scored.push((doc_id, score));
            }
        }
        scored.sort_by(|left, right| {
            right
                .1
                .total_cmp(&left.1)
                .then_with(|| left.0.cmp(&right.0))
        });
        scored.truncate(k);
        scored
    }

    fn quarter_weight(raw: u8) -> f32 {
        (raw as f32) * 0.25
    }

    fn signed_quarter_weight(raw: i8) -> f32 {
        (raw as f32) * 0.25
    }

    proptest! {
        #[test]
        fn top_k_weighted_matches_exact_sparse_dot_product(
            docs in prop::collection::vec(
                prop::collection::vec((0u8..20, 0u8..8), 0..16),
                0..40
            ),
            query in prop::collection::vec((0u8..20, -8i8..8i8), 0..12),
            k in 0usize..12,
            stride in prop::sample::select(vec![1u32, 97u32]),
        ) {
            let mut idx: PostingsIndex<String, f32> = PostingsIndex::new();
            let mut oracle_docs = Vec::new();

            for (i, doc_terms) in docs.iter().enumerate() {
                let doc_id = (i as DocId) * stride;
                let weighted_terms: Vec<(String, f32)> = doc_terms
                    .iter()
                    .map(|&(term, weight)| (format!("t{term:02}"), quarter_weight(weight)))
                    .collect();
                idx.add_weighted_document(doc_id, &weighted_terms).unwrap();

                let mut oracle_doc = std::collections::HashMap::new();
                for &(term, weight) in doc_terms {
                    *oracle_doc.entry(term).or_insert(0.0) += quarter_weight(weight);
                }
                oracle_docs.push((doc_id, oracle_doc));
            }

            let query_owned: Vec<(String, f32)> = query
                .iter()
                .map(|&(term, weight)| (format!("t{term:02}"), signed_quarter_weight(weight)))
                .collect();
            let query_refs: Vec<(&str, f32)> = query_owned
                .iter()
                .map(|(term, weight)| (term.as_str(), *weight))
                .collect();
            let oracle_query: Vec<(u8, f32)> = query
                .iter()
                .map(|&(term, weight)| (term, signed_quarter_weight(weight)))
                .collect();

            let ranked = idx.top_k_weighted(&query_refs, k);
            let expected = exact_sparse_top_k(&oracle_docs, &oracle_query, k);

            prop_assert_eq!(ranked, expected);
        }
    }

    #[test]
    fn top_k_weighted_zero_k_is_empty() {
        let mut idx: PostingsIndex<String, f32> = PostingsIndex::new();
        idx.add_weighted_document(0, &[(String::from("term"), 1.0)])
            .unwrap();

        assert!(idx.top_k_weighted(&[("term", 1.0)], 0).is_empty());
    }

    #[test]
    fn classic_u32_still_works_unchanged() {
        // Verify the default u32 path is backward compatible
        let mut idx: PostingsIndex<String> = PostingsIndex::new();
        idx.add_document(0, &[String::from("hello"), String::from("hello")])
            .unwrap();
        // "hello" appears twice -> tf=2
        assert_eq!(idx.term_frequency(0, "hello"), 2);
        assert_eq!(idx.document_len(0), 2); // 2 terms total
    }
}

//! Byte-backed raw segment reader experiments.
//!
//! This module is intentionally narrow. It supports one local, numeric-term,
//! `u32`-weighted raw segment format so query code can read posting lists
//! without reconstructing a full [`crate::PostingsIndex`].

use crate::codec::varint;
use crate::{CandidatePlan, DocId, PlannerConfig, PostingsIndex};
use std::collections::{btree_map::Entry, BTreeMap, HashMap};
use std::fs::File;
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::Path;

const MAGIC: &[u8; 8] = b"PSTRW001";
const FOOTER_MAGIC: &[u8; 8] = b"PSTRF001";
/// Current format. Version 4 adds a CRC32 of the 72-byte header to the
/// integrity section, since the header holds the checksum flag, the offsets,
/// and the length totals that no section CRC covers.
const VERSION: u32 = 4;
/// Last version without a header CRC. Still readable; a bit flip in the
/// header of such a segment can go undetected.
const VERSION_WITHOUT_HEADER_CRC: u32 = 3;
const HEADER_LEN: usize = 72;
const TERM_ENTRY_LEN: usize = 48;
const DOC_ENTRY_LEN: usize = 8;
const BLOCK_ENTRY_LEN: usize = 24;
const FOOTER_LEN: usize = 12;
const DEFAULT_BLOCK_SIZE: u32 = 128;
/// Header flag bit: the segment carries a content-integrity section (section
/// CRC32s + one CRC32 per posting block) between the postings region and the
/// footer. Readers that predate this flag reject it via `UnsupportedFlags`,
/// so they can never silently misread a checksummed segment.
const FLAG_CHECKSUMS: u32 = 1;
/// Fixed prefix of the integrity section: term-dir, doc-meta, block-dir, and
/// header CRC32s, in that order, followed by one CRC32 per block in directory
/// order. Version 3 segments have the same prefix without the header CRC.
const INTEGRITY_HEADER_LEN: usize = 16;
const INTEGRITY_HEADER_LEN_V3: usize = 12;
// Keep normal local-file queries on one read, but cap pathological high-DF term
// payloads so file-backed traversal cannot allocate an entire huge posting list.
const FILE_FULL_POSTINGS_READ_LIMIT: u64 = 1024 * 1024;

/// A numeric term id in the first raw postings format.
pub type RawTermId = u64;

type RawDocumentLengths = Vec<(DocId, u32)>;
type BorrowedRawTermPostings<'a> = Vec<(RawTermId, &'a [(DocId, u32)])>;

