        Self { term_id, postings }
    }

    /// Return the raw term id.
    pub fn term_id(self) -> RawTermId {
        self.term_id
    }

    /// Return the raw `(doc_id, weight)` postings.
    pub fn postings(self) -> &'a [(DocId, u32)] {
        self.postings
    }
}

/// Header metadata for a raw segment.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RawSegmentMeta {
    term_count: u32,
    doc_count: u32,
    max_doc_id: DocId,
    block_size: u32,
    total_doc_len: u64,
    term_dir_offset: u64,
    doc_meta_offset: u64,
    postings_offset: u64,
    footer_offset: u64,
    flags: u32,
    version: u32,
}

impl RawSegmentMeta {
    fn has_checksums(self) -> bool {
        self.flags & FLAG_CHECKSUMS != 0
    }

    fn has_header_crc(self) -> bool {
        self.version > VERSION_WITHOUT_HEADER_CRC
    }

    fn integrity_header_len(self) -> usize {
        if self.has_header_crc() {
            INTEGRITY_HEADER_LEN
        } else {
            INTEGRITY_HEADER_LEN_V3
        }
    }
}

impl RawSegmentMeta {
    /// Number of distinct terms in the segment.
    pub fn term_count(self) -> u32 {
        self.term_count
    }

    /// Number of documents in the segment.
    pub fn doc_count(self) -> u32 {
        self.doc_count
    }

    /// Highest document id in the segment, or zero for an empty segment.
    pub fn max_doc_id(self) -> DocId {
        self.max_doc_id
    }

    /// Target block size recorded for the segment.
    pub fn block_size(self) -> u32 {
        self.block_size
    }

    /// Sum of document lengths in the segment.
    pub fn total_doc_len(self) -> u64 {
        self.total_doc_len
    }

    /// Average document length.
    pub fn avg_doc_len(self) -> f32 {
        if self.doc_count == 0 {
            return 0.0;
        }
        self.total_doc_len as f32 / self.doc_count as f32
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TermEntry {
    term_id: RawTermId,
    df: u32,
    max_weight: u32,
    total_weight: u64,
    postings_offset: u64,
    postings_len: u32,
}

impl TermEntry {
    /// Capacity to reserve for this term's decoded postings.
    ///
    /// `df` comes from the file, so it cannot size an allocation on its own.
    /// Every posting is a doc-gap varint plus a weight varint, at least two
    /// bytes, so the postings bytes bound how many can really be there.
    fn posting_capacity(self) -> usize {
        (self.df as usize).min(self.postings_len as usize / 2)
    }
}

