        .enumerate()
        .map(|(offset, terms)| RawDocument::new(start_doc_id + offset as u32, terms))
        .collect();
    write_u64_u32_segment(&raw_docs).unwrap()
}

#[cfg(feature = "raw-segment")]
fn build_raw_numeric_fixture() -> (PostingsIndex<u64>, RawWeightedDocs, Vec<u8>) {
