#[cfg(feature = "raw-segment")]
fn numeric_query_terms(idx: &PostingsIndex<u64>, count: usize, min_df: u32) -> Vec<u64> {
    (0..VOCAB_SIZE as u64)
        .filter(|term| idx.df(term) >= min_df)
        .take(count)
        .collect()
}

